input.old_string:
trim_tmp=$(mktemp "${TMPDIR:-/tmp}/design-log-publish-trim.XXXXXX") || return 1
case "$name" in
    *.meta)
        larch_redact_strip_meta_cmd_json "$src" "$trim_tmp" || {
            rm -f "$trim_tmp"
            return 1
        }
        ;;
    *-output*.json)
        larch_redact_strip_json_result "$src" "$trim_tmp" || {
            rm -f "$trim_tmp"
            return 1
        }
        ;;
    *)
        cp "$src" "$trim_tmp" || {
            rm -f "$trim_tmp"
            return 1
        }
        ;;
esac

